import {sequenceKeyLimits} from './sequence-key-storage.js';
const programs=new WeakMap(),finite=(v,min,max)=>Number.isFinite(v)&&v>=min&&v<=max;
export function validSectionWeightCurve(keys){return keys===undefined||Array.isArray(keys)&&keys.length>0&&keys.length<=sequenceKeyLimits.perTrack&&keys.every((k,i)=>k&&Object.keys(k).every(p=>['time','value','interpolation'].includes(p))&&finite(k.time,0,86400)&&(!i?k.time===0:k.time>keys[i-1].time)&&finite(k.value,0,1)&&(k.interpolation===undefined||['linear','step'].includes(k.interpolation)));}
export function prepareSectionWeightCurve(keys){let p=programs.get(keys);if(p)return p;if(!keys||!validSectionWeightCurve(keys))throw Error('구간 가중치 키의 시간·값·보간을 확인하세요.');p={keys,upper(time,offset=0){let lo=0,hi=keys.length;while(lo<hi){const mid=(lo+hi)>>1;if(offset+keys[mid].time<=time)lo=mid+1;else hi=mid;}return lo;}};programs.set(keys,p);return p;}
export function sampleSectionWeightCurve(section,time){const keys=section?.weightCurve;if(!keys)return 1;if(!Number.isFinite(time))throw Error('구간 가중치 평가 시각을 확인하세요.');const p=prepareSectionWeightCurve(keys),offset=section.start??0,upper=p.upper(time,offset),a=keys[Math.max(0,upper-1)],b=keys[Math.min(upper,keys.length-1)];if(a===b||a.interpolation==='step'||time===offset+a.time)return a.value;const t=Math.max(0,Math.min(1,(time-offset-a.time)/(b.time-a.time)));return a.value+(b.value-a.value)*t;}
export function trimSectionWeightCurve(section,start){if(!section.weightCurve)return undefined;const keys=section.weightCurve,p=prepareSectionWeightCurve(keys),offset=section.start??0,upper=p.upper(start,offset),first=keys[Math.max(0,upper-1)],result=[{time:0,value:sampleSectionWeightCurve(section,start),...(upper&&first.interpolation?{interpolation:first.interpolation}:{})}];for(let i=upper;i<keys.length;i++)result.push({...keys[i],time:keys[i].time-(start-offset)});if(!validSectionWeightCurve(result))throw Error('가중치 곡선의 확장 범위를 확인하세요.');return result;}
export function editSectionWeightCurve(section,{operation,index,field,value}={}){
 if(!section)throw Error('시퀀스 구간을 선택하세요.');if(operation==='disable'){delete section.weightCurve;return;}
 let keys=section.weightCurve?.map(k=>({...k}));if(operation==='enable')keys=[{time:0,value:1},{time:section.duration,value:1}];
 else if(['increase','decrease','pulse'].includes(operation)){const duration=section.duration;keys=operation==='pulse'?[{time:0,value:0},{time:duration/2,value:1},{time:duration,value:0}]:[{time:0,value:operation==='increase'?0:1},{time:duration,value:operation==='increase'?1:0}];}
 else{if(!keys||!validSectionWeightCurve(keys))throw Error('가중치 곡선을 먼저 켜세요.');if(operation==='add'){if(keys.length>=sequenceKeyLimits.perTrack)throw Error('구간 가중치 키 예산을 넘어요.');if(keys.length===1)keys.push({time:section.duration,value:keys[0].value});else{let at=0;for(let i=1;i<keys.length-1;i++)if(keys[i+1].time-keys[i].time>keys[at+1].time-keys[at].time)at=i;const a=keys[at],b=keys[at+1],time=a.time+(b.time-a.time)/2;keys.splice(at+1,0,{time,value:sampleSectionWeightCurve({...section,weightCurve:keys},(section.start??0)+time),...(a.interpolation?{interpolation:a.interpolation}:{})});}}
  else if(!Number.isInteger(index)||index<0||index>=keys.length)throw Error('가중치 키를 선택하세요.');else if(operation==='remove'){if(index===0)throw Error('첫 가중치 키는 유지해 주세요.');keys.splice(index,1);}else if(operation==='update'){if(!['time','value','interpolation'].includes(field)||index===0&&field==='time')throw Error('가중치 키 속성을 확인하세요.');if(value===undefined)delete keys[index][field];else keys[index][field]=value;}else throw Error('가중치 곡선 편집 명령을 확인하세요.');}
 if(!validSectionWeightCurve(keys))throw Error('가중치 값은0~1, 첫 시간은0, 이후 시간은 오름차순으로 입력하세요.');section.weightCurve=keys;return keys;
}
export const sequenceWeightCurveContract={field:'optional section.weightCurve [{time,value,interpolation?}]; first time0, ordered unique times0..86400, value0..1, linear(default)|step; constant endpoint extension; optional keys beyond current section end are retained',weight:'effective child weight = parent * child asset * static section weight * section curve value at parentTime-section.start; curve uses section clock, independently of source loop/reverse/timeWarp',behavior:'normalized peers mix using these weights; lone nonzero normalized owner stays full strength, so this is relative layer mixing, not standalone opacity/audio fade; events/audio/discrete fields keep existing rules',trim:'front trim inserts the original boundary value/interpolation at new time0 and rebases remaining keys, retaining their source curve; extending left holds the original first value',control:'root SetWeight/SetBlendMode recomputes curve factor at current parent time; runtime.sequenceTree exposes authored static weight and instantaneous sectionCurveWeight; paused seek uses same evaluator',budget:'existing sequence keyBudget includes all section weight keys; per-curve limit uses existing65536 per-track rule; property list pages32; no object-count cap',cost:'no curve means constant1; weak prepared binary lookup directly in immutable key arrays, no per-frame sort or key copies; reweight only changed owners using existing child traversal; no timer/worker/GPU resource',remaining:['cubic/weighted tangents','standalone baseline-filled/additive blending','animation mixer action weights']};
